function render(){ $('#nav').innerHTML=nav.map(([id,i,n])=>`<button class="${view===id?'active':''}" onclick="go('${id}')">${i} <span>${esc(n)}</span></button>`).join('');$('#heading').textContent=nav.find(x=>x[0]===view)?.[2]||'MUSES';$('#dateLabel').textContent=new Date(selected+'T12:00:00').toLocaleDateString('tr-TR',{weekday:'long',day:'numeric',month:'long',year:'numeric'});$('#app').innerHTML=({home,calendar,english,flash,pole:poleView,habits:()=>`<div class="card"><label>Gün <input type="date" value="${selected}" onchange="setDate(this.value)"></label></div>${habitCards()}`,journal,awards,settings,goals:goalsView,atlas:atlasView,p90:p90View,swim:swimView,library:libraryView,resources:resourcesView})[view]();}const ATLAS_SEED=catalog.ATLAS_SEED ?? [];
