persist=function(){initV2();let n=achievements().filter(b=>b[2]>=b[3]).length;if(n>lastBadgeCount){sound('win');window.catCelebrating=true;setTimeout(()=>{window.catCelebrating=false},1800);toast('✨ Yeni başarı açıldı!')}lastBadgeCount=n;legacyPersist()};
xp=function(){return legacyXp()+p90count()*20+v2().moveLogs.length*8+v2().reading.length*5+v2().swim.length*10+Object.values(v2().chapterDone).filter(Boolean).length*5};
function catSvg(){let o=v2().outfit;return `<svg class="mimo ${window.catCelebrating?'celebrate':''}" viewBox="0 0 220 230" aria-label="${esc(v2().catName)} kedi karakteri"><ellipse cx="110" cy="213" rx="66" ry="9" fill="#c5b1be" opacity=".27"/><path class="mimo-tail" d="M151 177 C197 190 205 142 188 132" fill="none" stroke="#a67562" stroke-width="18" stroke-linecap="round"/><ellipse cx="111" cy="162" rx="50" ry="47" fill="#ead4be" stroke="#b58c78" stroke-width="2"/><ellipse cx="80" cy="197" rx="22" ry="13" fill="#ead4be" stroke="#b58c78"/><ellipse cx="140" cy="197" rx="22" ry="13" fill="#ead4be" stroke="#b58c78"/><path d="M61 90 L51 28 Q52 19 62 26 L98 51 M123 51 L158 26 Q167 19 167 30 L158 90" fill="#ead4be" stroke="#b58c78" stroke-width="2.5"/><path d="M62 43 L67 75 L85 57 M151 43 L145 74 L131 57" fill="#dca3a4"/><ellipse cx="110" cy="96" rx="65" ry="54" fill="#f3dfc8" stroke="#b58c78" stroke-width="2"/><path d="M96 46 L103 67 M111 44 L113 65 M126 47 L121 67" stroke="#c69a7c" stroke-width="5" stroke-linecap="round"/><g class="mimo-eyes"><ellipse cx="88" cy="95" rx="7" ry="10" fill="#4b433b"/><ellipse cx="132" cy="95" rx="7" ry="10" fill="#4b433b"/><circle cx="90" cy="92" r="2.2" fill="white"/><circle cx="134" cy="92" r="2.2" fill="white"/></g><ellipse cx="73" cy="111" rx="11" ry="6" fill="#e6a9a8" opacity=".7"/><ellipse cx="147" cy="111" rx="11" ry="6" fill="#e6a9a8" opacity=".7"/><path d="M103 107 Q110 101 117 107 L110 114Z" fill="#bb8181"/><path d="M110 114 Q105 123 99 117 M110 114 Q115 123 121 117" stroke="#795548" stroke-width="2" fill="none" stroke-linecap="round"/><g stroke="#ad8677" stroke-width="1.4" stroke-linecap="round"><path d="M77 111 L36 102 M77 117 L39 121 M143 111 L184 102 M143 117 L181 121"/></g>${o==='bow'?'<path d="M110 145 L83 132 Q76 149 85 163 L110 151 L135 163 Q144 149 137 132Z" fill="#a78ac7"/><circle cx="110" cy="148" r="8" fill="#7e5e9a"/>':o==='scarf'?'<path d="M66 137 Q110 151 154 137 L149 157 Q110 169 71 156Z" fill="#789879"/><path d="M134 154 L155 184 L133 192 L117 160" fill="#789879"/>':o==='sport'?'<path d="M48 78 Q110 62 172 78 L173 89 Q110 78 47 89Z" fill="#8d83c5"/><path d="M102 79 L117 79" stroke="white" stroke-width="4"/>':o==='cape'?'<path d="M74 137 L40 197 Q108 216 180 197 L146 137" fill="#ad8247" opacity=".9"/><circle cx="110" cy="147" r="9" fill="#f3c766"/>':o==='crown'?'<path d="M76 53 L70 19 L94 34 L110 11 L126 34 L150 19 L144 53Z" fill="#e7b953" stroke="#b38a3d" stroke-width="2"/><circle cx="110" cy="37" r="6" fill="#aa82c1"/>':' '}<path d="M94 174 Q110 185 126 174" fill="none" stroke="#c3a58e" stroke-width="2"/></svg>`}
function catPanel(){let n=p90count();return `<div class="card hero cat-card"><div><span class="tag">✦ ${esc(v2().catName)} · yol arkadaşın</span><h2 style="margin-top:10px">Küçük adımlar, büyük dönüşüm.</h2><p>${n?`90 günlük hedefte ${n} günü tamamladın.`:'Bir hedef seç, ilk başarını kazan.'} Kıyafetler gerçek tamamlamalarla açılır.</p>${progress(n,90)}<div class="flex"><button class="primary" onclick="go('goals')">Hedeflerim</button><button onclick="go('awards')">Kedi gardırobu</button><button onclick="v2().sound=!v2().sound;persist()">${v2().sound?'🔊 Ses açık':'🔇 Ses kapalı'}</button></div></div>${catSvg()}</div>`}
function goalsView(){return catPanel()+`<div class="card"><h2>Başlangıç · hedefini seç</h2><p>Bir veya birden fazla yol seçebilirsin. Sadece etkin yollar takvimine plan olarak yansır. Antrenman yükünü birlikte değerlendir.</p><label>Kedinin adı <input value="${esc(v2().catName)}" onchange="v2().catName=this.value.trim()||'Mimo';persist()"></label></div><div class="grid">${goalOptions.map(([id,ico,label])=>{let g=v2().goals[id];return `<div class="card"><span class="goal-icon">${ico}</span><h3>${esc(label)}</h3><label class="flex"><input type="checkbox" ${g?.active?'checked':''} onchange="setGoal('${id}',this.checked)"> Etkin hedef</label><label>Başlangıç <input type="date" value="${esc(g?.start||(id==='p90'?v2().p90Start:id==='pole'?S.poleStart:id==='english'?today():today()))}" onchange="goalDate('${id}',this.value)"></label>${id==='p90'?progress(p90count(),90):id==='pole'?progress(Object.values(S.pole).filter(x=>x.done).length,84):id==='english'?progress(Object.values(S.english).filter(x=>x.done).length,116):''}<button onclick="go('${({p90:'p90',pole:'pole',english:'english',read:'library',swim:'swim',piano:'journal',habit:'habits'})[id]}')">Yolu aç →</button></div>`}).join('')}</div><div class="notice">P90X ve pole antrenmanları aynı gün otomatik olarak birleştirilmez. Ağrı, uyuşma veya aşırı yorgunlukta hedefi ertele; dinlenme başarısızlık değildir.</div>`}
function setGoal(id,active){const g=v2().goals[id]??={start:id==='p90'?v2().p90Start:id==='pole'?S.poleStart:id==='english'?today():today()};g.active=active;v2().goalCreated=true;persist()}
function goalDate(id,d){if(!d)return;(v2().goals[id]??={active:false}).start=d;if(id==='p90')v2().p90Start=d;if(id==='pole')S.poleStart=d;persist()}
function setOutfit(o){let item=outfits.find(x=>x[0]===o);if(!item||p90count()<item[2])return;v2().outfit=o;sound('unlock');persist()}
awards=function(){return catPanel()+`<div class="card"><h2>🐾 ${esc(v2().catName)}'nun gardırobu</h2><div class="grid three">${outfits.map(([id,n,g])=>`<button class="wardrobe ${v2().outfit===id?'primary':''}" ${p90count()<g?'disabled':''} onclick="setOutfit('${id}')"><b>${['🐈','🎀','🧣','🎽','🦸','👑'][outfits.findIndex(x=>x[0]===id)]} ${n}</b><small>${p90count()>=g?'Açık':`${g} P90X günü · kilitli`}</small></button>`).join('')}</div></div><div class="grid three">${achievements().map(([i,t,v,g])=>`<div class="card"><div class="medal" style="opacity:${v>=g?1:.4}">${i}</div><h3>${esc(t)}</h3>${progress(Math.min(v,g),g)}<small>${v>=g?'Kazanıldı':'Henüz kilitli'}</small></div>`).join('')}</div><div style="margin-top:15px">${legacyAwards()}</div>`};
function v2stat(){let days=Array.from({length:7},(_,i)=>add(selected,i-6));let data=days.map(d=>{let tasks=tasksFor(d),ev=goalEvents(d);return {d,p:tasks.length+ev.length,c:tasks.filter(x=>x.done).length+ev.filter(x=>x.done).length}});let mx=Math.max(1,...data.map(x=>x.p));return `<div class="card"><h3>Son 7 gün · plan / tamamlanan</h3><div class="chart">${data.map(x=>`<div class="chartcol" title="${x.d} · ${x.c}/${x.p}"><div class="chartstack"><i style="height:${x.p/mx*100}%"></i><b style="height:${x.c/mx*100}%"></b></div><small>${x.d.slice(8)}</small></div>`).join('')}</div><div class="flex mini"><span>🟪 Plan</span><span>🟩 Tamamlanan</span></div><p class="muted mini">Dönem toplamı: ${data.reduce((a,b)=>a+b.c,0)} / ${data.reduce((a,b)=>a+b.p,0)}</p></div>`}
function deltaDays(a,b){return Math.round((new Date(b+'T12:00:00')-new Date(a+'T12:00:00'))/86400000)}
function goalEvents(d){let a=[],g=v2().goals;if(g.p90?.active){let n=deltaDays(v2().p90Start,d)+1;if(n>=1&&n<=90)a.push({label:p90title(n),done:!!p90entry(n).done,view:'p90',n})}if(g.pole?.active){let n=deltaDays(S.poleStart,d);if(pole[n])a.push({label:pole[n].title,done:!!S.pole[pole[n].id]?.done,view:'pole',n:pole[n].week})}if(g.english?.active){let n=deltaDays(g.english.start,d);if(n>=0&&n<812)a.push({label:'English Quest · hafta '+(Math.floor(n/7)+1),done:!!S.english[Math.floor(n/7)+1]?.done,view:'english',n:Math.floor(n/7)+1})}for(let [id,label,nm] of [['read','Kitap okuma','Kitap okuma'],['piano','Piyano','Piyano'],['habit','Günlük ritüeller','Su']])if(g[id]?.active&&d>=g[id].start)a.push({label,done:id==='habit'?habitValue(d,nm)>=2500:habitValue(d,nm)>=1,view:id==='read'?'library':id==='piano'?'journal':'habits'});return a}
function openEvent(v,n){if(v==='p90')pday=n;if(v==='pole')week=n;if(v==='english')engWeek=n;go(v)}
function eventsHtml(d){return goalEvents(d).map(e=>`<button class="eventpill ${e.done?'completed':''}" onclick="openEvent('${e.view}',${e.n||0})">${e.done?'✓':'○'} ${esc(e.label)}</button>`).join('')}
home=function(){return catPanel()+`<div class="grid">${v2stat()}<div class="card"><h3>Bugünkü etkin hedefler</h3>${eventsHtml(selected)||'<p class="muted">Hedeflerim ekranından bir yol seç.</p>'}<button onclick="go('goals')">Hedefleri düzenle</button></div></div>`+legacyHome()};
calendar=function(){let first=calMonth+'-01',a=new Date(first+'T12:00:00'),off=(a.getDay()+6)%7,last=new Date(a.getFullYear(),a.getMonth()+1,0).getDate(),list=Array.from({length:Math.ceil((off+last)/7)*7},(_,i)=>add(first,i-off)),start=add(selected,-((new Date(selected+'T12:00:00').getDay()+6)%7)),weekdays=Array.from({length:7},(_,i)=>add(start,i)),mdays=Array.from({length:last},(_,i)=>add(first,i));let ds=agendaMode==='week'?weekdays:agendaMode==='month'?mdays:[selected];let sums=ds.flatMap(d=>[...tasksFor(d),...goalEvents(d)]);return `<div class="card"><div class="flex between"><button onclick="shiftMonth(-1)">‹</button><h3>${a.toLocaleDateString('tr-TR',{month:'long',year:'numeric'})}</h3><button onclick="shiftMonth(1)">›</button></div><div class="days">${['Pt','Sa','Ça','Pe','Cu','Ct','Pa'].map(x=>`<small style="text-align:center">${x}</small>`).join('')}${list.map(d=>{let rows=[...tasksFor(d),...goalEvents(d)],done=rows.filter(x=>x.done).length;return `<button class="calendarcell ${d===selected?'sel':''} ${d.slice(0,7)!==calMonth?'dim':''}" onclick="setDate('${d}')"><b>${+d.slice(-2)}</b><br><small>${rows.length?`${done}/${rows.length}`:''}</small></button>`}).join('')}</div></div><div class="flex" style="margin-bottom:12px">${['day','week','month','kanban'].map((x,i)=>`<button class="${agendaMode===x?'primary':''}" onclick="agendaMode='${x}';render()">${['Gün','Hafta','Ay','Kanban'][i]}</button>`).join('')}<button onclick="setDate(today())">Bugün</button></div><div class="card"><b>${sums.filter(x=>x.done).length} tamamlanan · ${sums.filter(x=>!x.done).length} planlanan</b>${progress(sums.filter(x=>x.done).length,sums.length)}</div><div id="edit">${taskForm()}</div>${agendaMode==='kanban'?`<div class="kanban">${['Planlandı','Devam ediyor','Tamamlandı'].map(st=>`<div class="card"><h3>${st}</h3>${taskList(S.tasks.filter(t=>(t.status||'Planlandı')===st))}</div>`).join('')}</div>`:`<div class="${agendaMode==='week'?'weekgrid':'grid'}">${ds.map(d=>`<div class="card"><h3>${new Date(d+'T12:00:00').toLocaleDateString('tr-TR',{weekday:'short',day:'numeric',month:'short'})}</h3>${eventsHtml(d)}${taskList(tasksFor(d))}<button onclick="setDate('${d}');agendaMode='day';render()">Güne git</button></div>`).join('')}</div>`}${v2stat()}`};
function p90View(){let n=pday,x=p90entry(n),dvds=p90schedule(n),rest=!dvds.length;return catPanel()+`<div class="card"><div class="flex between"><div><h2>P90X Classic · Tur ${v2().p90Run}</h2><small>12 DVD · ${Object.values(P90_MOVES).flat().length} hareket / set satırı · 90 gün</small></div><button onclick="newP90Run()">Yeni tur</button></div><div class="flex"><label>Başlangıç <input type="date" value="${esc(v2().p90Start)}" onchange="goalDate('p90',this.value)"></label><button onclick="setGoal('p90',true)">Takvimime ekle</button></div>${progress(p90count(),90)}<div class="quest-road">${Array.from({length:90},(_,i)=>{let k=i+1,e=p90entry(k);return `<button class="quest-node ${k===n?'selected':''} ${e.done?'finished':''} ${k%30===0?'milestone':''}" onclick="pday=${k};render()" aria-label="Gün ${k}">${e.done?'✓':k%30===0?'🏆':k}</button>`}).join('')}</div></div><div class="card"><div class="flex between"><button onclick="pday=Math.max(1,pday-1);render()">‹</button><span class="tag">Gün ${n} · ${add(v2().p90Start,n-1)}</span><button onclick="pday=Math.min(90,pday+1);render()">›</button></div><h2>${esc(p90title(n))}</h2><div class="flex"><label>Gerçek süre (dk) <input class="short" type="number" min="0" value="${esc(x.minutes??'')}" onchange="p90Set('minutes',this.value)"></label><label>RPE <input class="short" type="number" min="1" max="10" value="${esc(x.rpe??'')}" onchange="p90Set('rpe',this.value)"></label><label>Kalori <input class="short" type="number" min="0" value="${esc(x.calories??'')}" onchange="p90Set('calories',this.value)"></label></div><label>Not <textarea onchange="p90Set('note',this.value)">${esc(x.note||'')}</textarea></label><button class="${x.done?'':'primary'}" onclick="p90Set('done',${!x.done})">${x.done?'✓ Tamamlandı · geri al':rest?'Dinlenme günü tamamlandı':'Günü tamamla'}</button></div>${(rest?[7]:dvds).map(d=>p90dvd(d,n)).join('')}<div class="notice">Hareket isimleri mevcut P90X takip defterinden. 7 diskin listesi resmî takip föyüne, kalan 5 disk ikincil kaynak derlemesine dayanır. Set tekrarlarını bilerek koruduk.</div>`}
function p90Set(k,val){(v2().p90[p90key(pday)]??={})[k]=val;if(k==='done'&&val)sound('win');persist()}
function newP90Run(){if(!confirm('Yeni tur başlatılsın mı? Önceki tur verileri korunur.'))return;v2().p90Run++;v2().p90Start=today();(v2().goals.p90??={active:false}).start=today();v2().outfit='plain';pday=1;persist()}
function p90dvd(d,n){let x=p90entry(n),arr=P90_MOVES[d]||[];return `<details class="card" ${d===p90schedule(n)[0]?'open':''}><summary><b>DVD ${String(d).padStart(2,'0')} · ${esc(DVD[d])}</b> · ${arr.length} satır</summary><div class="scroller"><table class="workouttable"><thead><tr><th>Hareket / set</th><th>Tekrar</th><th>Sağ</th><th>Sol</th><th>Kg</th><th>Sn</th><th>✓</th></tr></thead><tbody>${arr.map((m,i)=>{let key=d+'-'+i,z=x.moves?.[key]||{};return `<tr><td><b>${i+1}. ${esc(m)}</b><br><a target="_blank" rel="noopener" href="https://www.youtube.com/results?search_query=${encodeURIComponent('P90X '+m)}">Video ara ↗</a></td>${['reps','right','left','kg','seconds'].map(k=>`<td><input aria-label="${esc(m)} ${k}" type="number" min="0" step="${k==='kg'?'0.5':'1'}" value="${esc(z[k]??'')}" onchange="p90Move('${key}','${k}',this.value)"></td>`).join('')}<td><input type="checkbox" aria-label="Tamamlandı" ${z.done?'checked':''} onchange="p90Move('${key}','done',this.checked)"></td></tr>`}).join('')}</tbody></table></div></details>`}
function p90Move(key,k,val){let x=v2().p90[p90key(pday)]??={};((x.moves??={})[key]??={})[k]=val;save()}
function atlasRows(){let r=S.records.Moves_Master;if(r?.headers?.includes('Canonical Move')&&r.rows?.length){return r.rows.filter(row=>row[0]).map(row=>{let o=Object.fromEntries(r.headers.map((h,i)=>[h,row[i]]));return {id:o['Move ID'],name:o['Canonical Move'],level:o['Difficulty Band'],mode:o['Pole Mode'],details:o}})}return ATLAS_SEED}
function safeurl(u){return /^https?:\/\//i.test(String(u||''))?esc(u):''}
function moveStats(id){return v2().moveLogs.filter(x=>x.id===id)}
function atlasView(){let a=atlasRows(),f=a.filter(x=>(atlasLevel==='all'||x.level===atlasLevel)&&(!atlasFilter||Object.values(x).join(' ').toLowerCase().includes(atlasFilter.toLowerCase()))),start=atlasPage*24;if(start>=f.length){atlasPage=0;start=0}let m=a.find(x=>x.id===atlasSelected);return `<div class="card hero"><h2>Movement & Transition Atlas</h2><div class="num">${a.length}</div><p>Kaynak atlasındaki hareketler · Basic / Intermediate / Advanced · sağ ve sol ayrı.</p><div class="flex"><button onclick="go('pole')">12 haftalık program</button><button onclick="loadSheet('atlas','Moves_Master')">Tam kaynak ayrıntılarını getir</button><button onclick="loadSheet('atlas','Transitions')">Geçişleri getir</button></div></div>${m?moveDetail(m):''}<div class="card"><div class="flex"><input placeholder="Hareket ara" value="${esc(atlasFilter)}" oninput="atlasFilter=this.value;atlasPage=0;searchRender(this,'atlasFilter')"><select onchange="atlasLevel=this.value;atlasPage=0;render()">${['all','Basic','Intermediate','Advanced'].map(x=>`<option value="${x}" ${x===atlasLevel?'selected':''}>${x==='all'?'Tüm seviyeler':x}</option>`).join('')}</select><small>${f.length} hareket</small></div></div><div class="grid three">${f.slice(start,start+24).map(m=>{let a=v2().atlas[m.id]||{},l=moveStats(m.id);return `<button class="card movecard" onclick="atlasSelected='${esc(m.id)}';render();window.scrollTo(0,0)">${safeurl(a.image)?`<img src="${safeurl(a.image)}" alt="${esc(m.name)}" loading="lazy">`:`<div class="moveplaceholder">◌<small>Kaynak görseli eklenebilir</small></div>`}<span class="tag">${esc(m.level)}</span><h3>${esc(m.name)}</h3><small>${l.length} kayıt · sağ ${l.reduce((s,z)=>s+Number(z.right||0),0)} / sol ${l.reduce((s,z)=>s+Number(z.left||0),0)}</small></button>`}).join('')}</div><div class="flex between"><button ${atlasPage===0?'disabled':''} onclick="atlasPage--;render()">‹</button><small>${atlasPage+1} / ${Math.max(1,Math.ceil(f.length/24))}</small><button ${start+24>=f.length?'disabled':''} onclick="atlasPage++;render()">›</button></div>${S.records.Transitions?`<div class="card"><h3>Geçiş kayıtları</h3><p>${S.records.Transitions.rows.length} kaynak satırı yüklü.</p>${recordTable('Transitions',20)}</div>`:''}`}
function searchRender(el,k){let pos=el.selectionStart,ph=el.placeholder;render();let a=[...document.querySelectorAll('input')].find(x=>x.placeholder===ph);if(a){a.focus();try{a.setSelectionRange(pos,pos)}catch{}}}
function moveDetail(m){let a=v2().atlas[m.id]||{},logs=moveStats(m.id).slice().reverse(),det=m.details||{};return `<div class="card"><div class="flex between"><span class="tag">${esc(m.id)} · ${esc(m.level)}</span><button onclick="atlasSelected='';render()">Kapat ×</button></div><h2>${esc(m.name)}</h2><p>${esc(m.mode||'')}</p><div class="grid"><div>${safeurl(a.image)?`<img class="moveimage" src="${safeurl(a.image)}" alt="${esc(m.name)}">`:'<div class="moveplaceholder">Görsel eklenmedi</div>'}<label>Doğru hareket görselinin URL’si<input class="wide" type="url" value="${esc(a.image||'')}" onchange="moveMeta('${m.id}','image',this.value)"></label><label>Video bağlantısı<input class="wide" type="url" value="${esc(a.video||'')}" onchange="moveMeta('${m.id}','video',this.value)"></label>${safeurl(a.video)?`<a href="${safeurl(a.video)}" target="_blank" rel="noopener">Videoyu aç</a>`:`<a href="https://www.youtube.com/results?search_query=${encodeURIComponent(m.name+' pole dance tutorial')}" target="_blank" rel="noopener">Eğitmen videosu ara ↗</a>`}<p><a href="${sources.atlas}" target="_blank" rel="noopener">Orijinal atlas ↗</a></p></div><form onsubmit="logMove(event,'${m.id}')"><h3>Antrenman kaydı</h3><div class="flex"><label>Tarih <input type="date" name="date" required value="${selected}"></label><label>Mod <select name="mode"><option>Spinning</option><option>Static</option></select></label></div><div class="grid"><label>Sağ tekrar <input type="number" name="right" min="0" value="0" required></label><label>Sol tekrar <input type="number" name="left" min="0" value="0" required></label><label>Sağ tutuş (sn) <input type="number" name="rightSec" min="0"></label><label>Sol tutuş (sn) <input type="number" name="leftSec" min="0"></label><label>Sağ seviye <select name="rightLevel">${['Denemedim','Yardımlı','Bağımsız','Temiz','Akıcı'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Sol seviye <select name="leftLevel">${['Denemedim','Yardımlı','Bağımsız','Temiz','Akıcı'].map(x=>`<option>${x}</option>`).join('')}</select></label></div><textarea name="note" placeholder="Grip, giriş / çıkış, not, video değerlendirmesi"></textarea><button class="primary">Kaydı ekle</button></form></div>${Object.keys(det).length?`<details><summary>Kaynak ayrıntıları</summary>${Object.entries(det).filter(([k,v])=>v).map(([k,v])=>`<p><b>${esc(k)}</b> · ${esc(v)}</p>`).join('')}</details>`:'<small>32 sütunluk teknik açıklamaları Drive bağlantısı üzerinden getir.</small>'}<h3 style="margin-top:12px">Geçmiş · ${logs.length} kayıt</h3>${logs.map(z=>`<div class="line"><div>${esc(z.date)} · ${esc(z.mode)}<br><b>Sağ ${esc(z.right)} · sol ${esc(z.left)}</b> · ${esc(z.rightLevel)} / ${esc(z.leftLevel)}<br>${esc(z.note)}</div></div>`).join('')||'<p class="muted">İlk kaydını ekle.</p>'}</div>`}
function moveMeta(id,k,val){(v2().atlas[id]??={})[k]=val;persist()}
