function bookRows(){let map=new Map(BOOK_SEED.map(b=>[b.title,{...b}]));for(let r of recordObjects('Kitaplar')){let title=r.Kitap;if(!title)continue;let b=map.get(title)||{id:'notion-'+String(r['Notion ID']||r.URL||title).replace(/[^a-zA-Z0-9-]/g,''),title};Object.assign(b,{author:r.Yazar||b.author,pages:Number(r['Toplam sayfa'])||b.pages,category:r.Kategori||b.category,summary:r.Notlar||b.summary,start:r['Başlangıç']||b.start,link:r['Drive PDF']||b.link,url:r.URL||b.url});map.set(title,b)}return [...map.values()].map(b=>({...b,...v2().bookMeta[b.id]}))}
function coverHtml(b){return safeurl(b.cover)?`<img class="bookcover" src="${safeurl(b.cover)}" alt="${esc(b.title)} kitap kapağı" loading="lazy" onerror="this.style.display='none'">`:`<div class="bookcover bookfallback"><span>${esc(b.category||'Kitap')}</span><b>${esc(b.title)}</b><small>${esc(b.author||'')}</small><em>Kapak bekliyor</em></div>`}
function libraryView(){let all=bookRows(),cats=[...new Set(all.map(x=>x.category||'Kategorisiz'))].sort(),f=all.filter(b=>(bookCategory==='all'||(b.category||'Kategorisiz')===bookCategory)&&(!libraryFilter||[b.title,b.author,b.category].join(' ').toLocaleLowerCase('tr').includes(libraryFilter.toLocaleLowerCase('tr')))),b=all.find(x=>x.id===bookSelected),n=f.length,start=bookPage*24;if(start>=n){bookPage=0;start=0}return `<div class="card hero"><h2>Reading Room</h2><div class="grid three"><div><div class="num">${all.filter(x=>!x.title.includes('(seçilecek)')).length}</div>Kitap</div><div><div class="num">${all.filter(b=>b.pages&&Number(v2().books[b.id]||0)>=b.pages).length}</div>Bitirilen</div><div><div class="num">${v2().reading.reduce((s,x)=>s+Number(x.pages||0),0)}</div>Yeni okunan sayfa</div></div><p>Notion kitaplığı: kayıtlı sayfa değerleri baskı doğrulaması gerektirebilir.</p><button onclick="loadNotion('Kitaplar')">Notion kitaplarını yenile</button></div>${b?bookDetail(b):''}<div class="card"><div class="flex"><input placeholder="Kitap veya yazar ara" value="${esc(libraryFilter)}" oninput="libraryFilter=this.value;bookPage=0;searchRender(this)"><select onchange="bookCategory=this.value;bookPage=0;render()"><option value="all">Tüm kategoriler</option>${cats.map(c=>`<option ${c===bookCategory?'selected':''}>${esc(c)}</option>`).join('')}</select><small>${n} sonuç</small></div></div><div class="grid three">${f.slice(start,start+24).map(b=>`<button class="card booktile" onclick="bookSelected='${esc(b.id)}';catalogMatches=[];render();window.scrollTo(0,0)">${coverHtml(b)}<div><h3>${esc(b.title)}</h3><small>${esc(b.author||'Yazar seçilecek')} · ${b.pages?b.pages+' s.':'Sayfa bilinmiyor'}</small><p class="mini">${esc(b.category||'Kategori seçilecek')}</p>${b.pages?progress(v2().books[b.id]||0,b.pages):'<small>Sayfa bilgisi bekliyor</small>'}</div></button>`).join('')}</div><div class="flex between"><button ${bookPage===0?'disabled':''} onclick="bookPage--;render()">‹</button><small>${bookPage+1}/${Math.max(1,Math.ceil(n/24))}</small><button ${start+24>=n?'disabled':''} onclick="bookPage++;render()">›</button></div><form class="card" onsubmit="newBook(event)"><h3>Yeni kitap</h3><div class="flex"><input name="title" required placeholder="Kitap adı"><input name="author" placeholder="Yazar"><input name="pages" type="number" min="1" placeholder="Sayfa"><input name="category" placeholder="Kategori"></div><button class="primary">Kitap ekle</button></form>`}
function newBook(e){e.preventDefault();let b=Object.fromEntries(new FormData(e.target)),id='local-'+uid();v2().bookMeta[id]={...b,id,pages:Number(b.pages)||0,local:true};BOOK_SEED.push({id,title:b.title});persist()}
function bookDetail(b){let count=Number(v2().books[b.id]||0);return `<div class="card"><div class="flex between"><span class="tag">${esc(b.category||'Kitap')}</span><button onclick="bookSelected='';catalogMatches=[];render()">Kapat ×</button></div><div class="bookdetail">${coverHtml(b)}<div><h2>${esc(b.title)}</h2><p>${esc(b.author||'Yazar teyidi gerekli')} · ${b.pages?b.pages+' sayfa (kayıtlı baskı)':'Sayfa sayısı doğrulanmadı'}</p><p>${esc(b.summary||'Özet henüz eklenmedi.')}</p><small>${b.publisherSource?'Yayınevi / katalog özeti':b.source==='notion'?'Notion konu notu':'Kayıt açıklaması'}</small>${safeurl(b.publisherSource)?`<p><a href="${safeurl(b.publisherSource)}" target="_blank" rel="noopener">Yayınevi / katalog kaynağı ↗</a></p>`:''}${safeurl(b.link)?`<p><a href="${safeurl(b.link)}" target="_blank" rel="noopener">Kitap / PDF bağlantısı ↗</a></p>`:''}${b.pages?progress(count,b.pages):`<p>${count} sayfa kaydedildi.</p>`}<form onsubmit="readBook(event,'${b.id}')" class="flex"><label>Okunan yeni sayfa <input name="pages" type="number" min="1" required></label><input name="date" type="date" value="${selected}" required><button class="primary">Oturumu kaydet</button></form><div class="flex"><button onclick="lookupBook('${b.id}')" ${libraryBusy?'disabled':''}>${libraryBusy?'Katalog aranıyor…':'Baskı ve kapak ara'}</button><a target="_blank" rel="noopener" href="https://books.google.com/books?q=${encodeURIComponent(b.title+' '+(b.author||''))}">Google Books ↗</a></div></div></div><details class="card"><summary>Kitap bilgilerini / kapağı düzelt</summary><form onsubmit="editBook(event,'${b.id}')"><div class="grid"><label>Başlık<input name="title" required value="${esc(b.title)}"></label><label>Yazar<input name="author" value="${esc(b.author||'')}"></label><label>Toplam sayfa<input name="pages" type="number" min="1" value="${esc(b.pages||'')}"></label><label>Kategori<input name="category" value="${esc(b.category||'')}"></label><label>Kapak URL<input name="cover" type="url" value="${esc(b.cover||'')}"></label><label>ISBN<input name="isbn" value="${esc(b.isbn||'')}"></label><label>Kaynak URL<input name="publisherSource" type="url" value="${esc(b.publisherSource||'')}"></label><label>Okunan toplam<input name="readTotal" type="number" min="0" value="${count}"></label></div><textarea name="summary">${esc(b.summary||'')}</textarea><button class="primary">Bilgileri kaydet</button></form></details>${catalogMatches.length?`<div class="card"><h3>Baskıyı doğrula ve seç</h3><p>Sayfa ve kapak bilgisi baskıya göre değişir. Otomatik birleştirme yapılmaz.</p>${catalogMatches.map((c,i)=>`<div class="line">${safeurl(c.cover)?`<img width="54" src="${safeurl(c.cover)}" alt="Kapak adayı">`:''}<div><b>${esc(c.title)}</b><br>${esc(c.author)} · ${esc(c.publisher||'')} · ${esc(c.year||'')} · ${c.pages||'?'} sayfa<br><small>ISBN ${esc(c.isbn||'—')}</small></div><button onclick="applyBookMatch('${b.id}',${i})">Bu baskı</button></div>`).join('')}</div>`:''}<h3>Okuma geçmişi</h3>${v2().reading.filter(x=>x.id===b.id).slice().reverse().map(x=>`<div class="line">${esc(x.date)} · +${esc(x.pages)} sayfa</div>`).join('')||'<p class="muted">Yeni oturum yok.</p>'}</div>`}
function readBook(e,id){e.preventDefault();let x=Object.fromEntries(new FormData(e.target)),b=bookRows().find(x=>x.id===id),a=Number(v2().books[id]||0),n=Number(x.pages);if(b.pages&&a+n>b.pages){toast('Toplam sayfa sınırını aşıyor; baskıyı veya okunan sayfayı kontrol et.');return}v2().books[id]=a+n;v2().reading.push({...x,id,logid:uid()});(S.habits[x.date]??={})['Kitap okuma']=1;sound('win');persist()}
function editBook(e,id){e.preventDefault();let b=Object.fromEntries(new FormData(e.target));let n=Number(b.readTotal);b.pages=Number(b.pages)||0;if(b.pages&&n>b.pages)return toast('Okunan toplam sayfa, kitap sayfasını aşamaz.');delete b.readTotal;Object.assign(v2().bookMeta[id]??={},b);v2().books[id]=n;persist()}
async function lookupBook(id){let b=bookRows().find(x=>x.id===id);if(!b)return;libraryBusy=true;catalogMatches=[];render();try{let q=b.isbn?'isbn:'+b.isbn:'intitle:'+b.title.split(' • ')[0]+(b.author?' inauthor:'+b.author.split(';')[0]:'');let r=await fetch('https://www.googleapis.com/books/v1/volumes?maxResults=8&q='+encodeURIComponent(q));if(!r.ok)throw Error('Katalog erişimi '+r.status);let j=await r.json();catalogMatches=(j.items||[]).map(({volumeInfo:v})=>({title:v.title,author:(v.authors||[]).join(', '),publisher:v.publisher,year:v.publishedDate,pages:v.pageCount,isbn:(v.industryIdentifiers||[]).find(x=>x.type==='ISBN_13')?.identifier,cover:v.imageLinks?.thumbnail?.replace(/^http:/,'https:'),summary:v.description?.replace(/<[^>]*>/g,' ').slice(0,350),link:v.infoLink?.replace(/^http:/,'https:')}));if(!catalogMatches.length)toast('Baskı bulunamadı. ISBN veya yayınevi sayfasını kullan.')}catch(e){toast('Çevrimiçi katalog açılamadı. Elle kapak URL’si ekleyebilirsin.')}finally{libraryBusy=false;render()}}
function applyBookMatch(id,i){let c=catalogMatches[i];if(!c)return;let old=bookRows().find(b=>b.id===id);if(c.pages&&Number(v2().books[id]||0)>c.pages)return toast('Bu baskının sayfası mevcut ilerlemenden az.');Object.assign(v2().bookMeta[id]??={},{author:c.author||old.author,pages:c.pages||old.pages,cover:c.cover||old.cover,isbn:c.isbn||old.isbn,publisherSource:c.link||old.publisherSource,summary:c.summary||old.summary});catalogMatches=[];persist()}
function resourceRows(){let map=new Map(RESOURCE_SEED.map(r=>[r.id,{...r}]));for(let r of recordObjects('İngilizce kaynaklar')){let id=String(r['Notion ID']||r.URL||'').replace(/-/g,'').match(/[0-9a-f]{32}/)?.[0];if(!id||!r['Goal name'])continue;let old=map.get(id)||{id};Object.assign(old,{title:r['Goal name'],week:Number(r['Açılış haftası'])||old.week,minutes:Number(r['Haftalık süre (dk)'])||old.minutes,pages:Number(r['Sayfa sayısı'])||old.pages,type:r['Kaynak türü']||old.type,method:r['Çalışma yöntemi']||old.method,cover:r.Kapak||old.cover});map.set(id,old)}return [...map.values()]}
function sourceTree(r){let live=recordObjects('İngilizce bölümler').filter(x=>String(x.Kaynak||'').replace(/-/g,'').includes(r.id)).sort((a,b)=>Number(a.Sıra||0)-Number(b.Sıra||0));let base=live.length?live.map((x,i)=>{let id=String(x['Notion ID']||x.URL||'').replace(/-/g,'').match(/[0-9a-f]{32}/)?.[0]||r.id+'-live-'+i,sub=String(x['Alt konular']||'').trim();return {id,title:x.İçerik||'Bölüm',note:x['Sayfa / süre']||'',checked:x.Tamamlandı===true||x.Tamamlandı==='__YES__',children:sub?sub.split(/\n|\s*;\s*/).filter(Boolean).map((s,j)=>({id:id+'-sub-'+j,title:s,children:[]})):[]}}):seedTree(r);let custom=v2().sourceNodes[r.id]||[],tree=base.map(x=>({...x,children:(x.children||[]).slice()}));function attach(nodes,parent){for(let x of custom.filter(a=>a.parent===parent)){let child={...x,children:[]};nodes.push(child);attach(child.children,child.id)}for(let x of nodes.filter(x=>!custom.some(a=>a.id===x.id))){x.children=x.children||[];attach(x.children,x.id)}}attach(tree,'');return tree}
function seedTree(r){let n=r.count||0,unit=r.unit||'Bölüm',known=r.known||[];return Array.from({length:n||known.length},(_,i)=>{let id=r.id+'-'+(i+1),t=known[i]||unit+' '+String(i+1).padStart(2,'0');let steps=r.id===RESOURCE_SEED[0]?.id?['Metin ve ilk dinleme','Vocabulary','Mini-Story','Point of View (varsa)','Audio Article','14 günlük tekrar ve değerlendirme']:[];return {id,title:t,checked:false,children:steps.map((s,j)=>({id:id+'-'+j,title:s,children:[]}))}})}
function leaves(nodes){return nodes.flatMap(n=>n.children?.length?leaves(n.children):[n])}function leafDone(n){return v2().chapterDone[n.id]??!!n.checked}function nodeDone(n){return n.children?.length?n.children.every(nodeDone):leafDone(n)}function markNode(id,val){let r=resourceRows().find(x=>x.id===sourceSelected);if(!r)return;let tree=sourceTree(r);function find(xs){for(let x of xs){if(x.id===id)return x;let a=find(x.children||[]);if(a)return a}}let n=find(tree);if(!n)return;for(let x of leaves([n]))v2().chapterDone[x.id]=val;if(val)sound('win');persist()}
function addNested(e,parent){e.preventDefault();let f=Object.fromEntries(new FormData(e.target));let ar=v2().sourceNodes[sourceSelected]??=[];ar.push({id:'node-'+uid(),parent,title:f.title,children:[]});persist()}
function nodeHTML(nodes,depth=0){return nodes.map(n=>`<div class="tree-node" style="--depth:${Math.min(6,depth)}"><div class="line"><input type="checkbox" ${nodeDone(n)?'checked':''} onchange="markNode('${esc(n.id)}',this.checked)"><div><b>${esc(n.title)}</b>${n.note?`<small> · ${esc(n.note)}</small>`:''}${n.children?.length?`<small> · ${n.children.filter(nodeDone).length}/${n.children.length}</small>`:''}</div></div>${n.children?.length?`<details ${depth===0?'':'open'}><summary>Alt bölümler (${n.children.length})</summary>${nodeHTML(n.children,depth+1)}</details>`:''}<details class="mini"><summary>Alt konu ekle</summary><form class="flex" onsubmit="addNested(event,'${esc(n.id)}')"><input name="title" required placeholder="Alt konu adı"><button>+ Ekle</button></form></details></div>`).join('')}
function resourcesView(){let arr=resourceRows(),f=arr.filter(r=>!sourceFilter||r.title.toLowerCase().includes(sourceFilter.toLowerCase())),r=arr.find(x=>x.id===sourceSelected);return `<div class="card hero"><h2>English Resource Library</h2><p>${arr.length} kaynak · bölüm → alt bölüm → alt konu. Notion kayıtları ve kişisel eklemeler ayrı tutulur. Sayılı örnek bölüm şablonları, gerçek bölüm adları aktarılana kadar yalnızca planlama içindir.</p><div class="flex"><button onclick="go('english')">116 haftalık yol</button><button onclick="syncLearning()">Notion kaynak ve dersleri getir</button></div></div>${r?resourceDetail(r):''}<div class="card"><input placeholder="Kaynak ara" value="${esc(sourceFilter)}" oninput="sourceFilter=this.value;searchRender(this)"></div><div class="grid three">${f.map(x=>{let t=leaves(sourceTree(x)),d=t.filter(leafDone).length;return `<button class="card resource-tile" onclick="sourceSelected='${x.id}';render();window.scrollTo(0,0)"><span class="tag">${esc(x.type||'İngilizce kaynak')}</span><h3>${esc(x.title)}</h3>${x.week?`<small>Açılış: ${x.week}. hafta · ${x.minutes||'—'} dk/hafta</small>`:''}${t.length?progress(d,t.length):'<small>Bölüm verisi aktarılacak</small>'}</button>`}).join('')}</div>`}
function resourceDetail(r){let tree=sourceTree(r),t=leaves(tree),done=t.filter(leafDone).length;return `<div class="card"><div class="flex between"><span class="tag">${esc(r.type||'Kaynak')}</span><button onclick="sourceSelected='';render()">Kapat ×</button></div><h2>${esc(r.title)}</h2>${r.method?`<p>${esc(r.method)}</p>`:''}${t.length?progress(done,t.length):'<p class="muted">Gerçek içerik listesini Notion’dan içe aktar veya alt bölüm ekle. Tam içerik henüz yerel dosyada yok.</p>'}<div class="flex"><a target="_blank" rel="noopener" href="https://app.notion.com/p/${r.id}">Orijinal Notion sayfası ↗</a><button onclick="importSourceBlocks('${r.id}')">Sayfadaki iç içe blokları getir</button><a href="https://books.google.com/books?q=${encodeURIComponent(r.title.split(' • ')[0])}" target="_blank" rel="noopener">Kitap baskısı ara ↗</a></div><form class="flex" onsubmit="addNested(event,'')"><input name="title" required placeholder="Yeni bölüm adı"><button class="primary">+ Bölüm</button></form><div style="margin-top:12px">${nodeHTML(tree)}</div></div>`}
async function syncLearning(){if(syncing)return;syncing=true;try{await loadNotion('İngilizce kaynaklar');await loadNotion('İngilizce bölümler')}finally{syncing=false;render()}}
async function importSourceBlocks(id){if(!cloud)return toast('Bu işlem Apps Script + Notion bağlantısı gerektirir.');try{let p=await rpc('studioNotionTree',id);let old=(v2().sourceNodes[id]||[]).filter(x=>!x.fromNotion);v2().sourceNodes[id]=old.concat(p.nodes);for(let x of p.nodes)if(x.checked&&v2().chapterDone[x.id]===undefined)v2().chapterDone[x.id]=true;toast(p.nodes.length+' blok aktarıldı.');persist()}catch(e){toast(e.message||String(e))}}
english=function(){return `<div class="grid"><div class="card"><h3>Kaynak ve bölüm ağacı</h3><p>Kitap, kurs, ders, alt konular.</p><button class="primary" onclick="go('resources')">Kaynakları aç</button></div><div class="card"><h3>Kelime çalışması</h3><button onclick="go('flash')">Flashcard Studio</button></div></div>`+legacyEnglish()};
async function syncAll(){if(!cloud)return toast('Tam veri aktarımı için Apps Script sürümünü kur.');if(syncing)return;syncing=true;try{for(let [src,tab] of [['atlas','Moves_Master'],['atlas','Transitions'],['atlas','Combos'],['atlas','Conditioning'],['pole','EXERCISE_LIBRARY_12W'],['pole','COMBO_BUILDER']])await loadSheet(src,tab);for(let name of notionNames)await loadNotion(name);await loadWords();toast('Aktarım denemesi tamamlandı; veri durumunu kontrol et.')}finally{syncing=false;render()}}
settings=function(){return `<div class="card"><h2>Aktarım denetimi</h2><p>Yerel paket: ${atlasRows().length} hareket · ${bookRows().length} kitap · ${resourceRows().length} kaynak.</p><button class="primary" onclick="syncAll()">Tüm bağlı kaynakları içe aktar</button><p><small>İçe aktarma asıl Notion veya Drive verilerini silmez. Tamamlanma bilgisi bu cihazda tutulur; bulut eşitleme mevcut Apps Script işleviyle ayrı ayrı yapılır.</small></p></div>`+legacySettings()};
/* Restore custom books across reload, without mutating source snapshot. */
const originalBookRows=bookRows;bookRows=function(){let r=originalBookRows(),ids=new Set(r.map(b=>b.id));for(let [id,b] of Object.entries(v2().bookMeta))if(b.local&&!ids.has(id))r.push({...b,id});return r};

