const M3_P90_CHEST = catalog.M3_P90_CHEST ?? [];
const norm3=s=>String(s||'').toLowerCase().replace(/[^a-z0-9]/g,'');
function yt3(u){try{let x=new URL(u),h=x.hostname.replace(/^www\./,'');if(h==='youtu.be')return /^[\w-]{11}$/.test(x.pathname.slice(1))?x.pathname.slice(1):'';if(['youtube.com','m.youtube.com','youtube-nocookie.com'].includes(h)){let id=x.searchParams.get('v')||x.pathname.match(/^\/(?:shorts|embed)\/([\w-]{11})/)?.[1];return /^[\w-]{11}$/.test(id||'')?id:''}}catch{}return ''}
function m3(id,name,kind='pole'){let u=kind==='pole'?(v2().atlas[id]||{}):(v2().exerciseMedia?.[id]||{}),base=kind==='pole'?{...(M3_IMAGES[id]?{image:'https://polemovebook.com/images/moves/'+M3_IMAGES[id]+'.webp',source:'https://polemovebook.com/collection/Bare-Necessities',credit:'PoleMovebook · kaynak koleksiyon görseli'}:{}),...M3_POLE[id]}:{};if(kind==='p90'&&M3_P90_CHEST.some(n=>norm3(name.replace(/^[A-Z]+\s*-\s*/,''))===norm3(n)))base={yt:'j4YMB3gHyNE',source:'https://www.youtube.com/watch?v=j4YMB3gHyNE',credit:'Todd Warren · çok hareketli P90X göğüs videosu',group:true};let video=u.video|| (base.yt?'https://www.youtube.com/watch?v='+base.yt:'');let yt=yt3(video),image=u.image||base.image||(!base.group&&yt?'https://i.ytimg.com/vi/'+yt+'/hqdefault.jpg':'');return {...base,image,video,yt,custom:!!(u.image||u.video),source:base.source||'',name,kind,id};}
function image3(u){return /^data:image\/(?:jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(String(u))?esc(u):safeurl(u)}
function mediaSearch3(name,kind,mode){let q=(kind==='pole'?name+' pole dance tutorial':'P90X '+name+' exercise demonstration');return (mode==='img'?'https://www.google.com/search?tbm=isch&q=':'https://www.youtube.com/results?search_query=')+encodeURIComponent(q)}
function thumb3(m){return `<div class="media-thumb">${image3(m.image)?`<img src="${image3(m.image)}" alt="${esc(m.name)} kaynak önizleme" loading="lazy" onerror="this.hidden=true;this.parentElement.classList.add('missing')">`:''}<div class="media-placeholder"><span>◈</span><small>${m.image?'Görsel yüklenemedi':'Görsel bekliyor'}</small></div>${m.yt?'<span class="play-dot">▶</span>':''}</div>`}
function mediaFields3(m){return `<div class="media-actions">${m.video?`<button class="primary" onclick="showMedia3('${m.kind}','${esc(m.id)}')">▶ Videoyu izle</button>`:''}${m.source?`<a href="${safeurl(m.source)}" target="_blank" rel="noopener">Kaynak ↗</a>`:''}<a href="${mediaSearch3(m.name,m.kind,'video')}" target="_blank" rel="noopener">Video ara ↗</a><a href="${mediaSearch3(m.name,m.kind,'img')}" target="_blank" rel="noopener">Görsel ara ↗</a></div>`}
function mediaEditor3(m){let u=m.kind==='pole'?(v2().atlas[m.id]||{}):(v2().exerciseMedia?.[m.id]||{});return `<details class="media-editor"><summary>Medya düzenle · kendi fotoğrafın veya bağlantın</summary><form onsubmit="saveMedia3(event,'${m.kind}','${esc(m.id)}')"><label>Görsel URL<input class="wide" name="image" type="url" value="${esc(/^https?:/.test(u.image||'')?u.image:'')}" placeholder="https://..."></label><label>Video URL<input class="wide" name="video" type="url" value="${esc(u.video||'')}" placeholder="YouTube veya video bağlantısı"></label><div class="flex"><button class="primary">Bağlantıları kaydet</button><label class="upload3">📷 Fotoğraf seç<input type="file" accept="image/*" onchange="uploadMedia3(this,'${m.kind}','${esc(m.id)}')"></label></div></form><small>Yerel fotoğraf küçültülerek saklanır. Video dosyası yüklemek yerine paylaşım bağlantısı kullan.</small><button onclick="clearMedia3('${m.kind}','${esc(m.id)}')">Kişisel medyayı sıfırla</button></details>`}
function userMedia3(kind,id){if(kind==='pole')return v2().atlas[id]??={};v2().exerciseMedia??={};return v2().exerciseMedia[id]??={}}
function saveMedia3(e,kind,id){e.preventDefault();let f=Object.fromEntries(new FormData(e.target)),u=userMedia3(kind,id);if(f.image||!String(u.image||'').startsWith('data:'))u.image=f.image;u.video=f.video;persist();toast('Medya kaydedildi')}
function clearMedia3(kind,id){let u=userMedia3(kind,id);delete u.image;delete u.video;persist()}
function uploadMedia3(el,kind,id){let file=el.files[0];if(!file)return;let reader=new FileReader();reader.onload=()=>{let im=new Image();im.onload=()=>{let c=document.createElement('canvas'),r=Math.min(1,560/Math.max(im.width,im.height));c.width=Math.round(im.width*r);c.height=Math.round(im.height*r);c.getContext('2d').drawImage(im,0,0,c.width,c.height);userMedia3(kind,id).image=c.toDataURL('image/jpeg',.72);persist();toast('Fotoğraf yerel olarak kaydedildi')};im.onerror=()=>toast('Fotoğraf açılamadı. JPG veya PNG seç.');im.src=reader.result};reader.readAsDataURL(file)}
function p90Catalog3(){return Object.entries(P90_MOVES).flatMap(([d,ms])=>ms.map((name,i)=>({id:d+'-'+i,name,d:Number(d),i}))) }
function findMedia3(kind,id){let x=kind==='pole'?atlasRows().find(x=>x.id===id):p90Catalog3().find(x=>x.id===id);return x?m3(id,x.name,kind):null}
function showMedia3(kind,id){let m=findMedia3(kind,id);if(!m)return;let dialog=$('#mediaDialog3');if(!dialog)return;dialog.innerHTML=`<div class="dialog-head"><div><small>${m.kind==='pole'?'Pole Atlas':'P90X'} · ${esc(m.credit||'Kişisel medya')}</small><h2>${esc(m.name)}</h2></div><button aria-label="Kapat" onclick="closeMedia3()">×</button></div>${m.yt?`<div class="video-frame"><iframe title="${esc(m.name)} video" src="https://www.youtube-nocookie.com/embed/${m.yt}?playsinline=1&rel=0" allow="accelerometer; encrypted-media; gyroscope; picture-in-picture; fullscreen" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div><p class="muted mini">YouTube yerel HTML dosyasında veya bazı cihazlarda gömülü oynatmayı engelleyebilir.</p>`:m.video?`<p>Bu kaynak harici oynatıcı gerektiriyor.</p>`:thumb3(m)}${m.video?`<a class="linkbutton" href="${safeurl(m.video)}" target="_blank" rel="noopener">Orijinal videoyu aç ↗</a>`:''}${mediaFields3(m)}${m.group?'<small>Bu video birden fazla P90X hareketini içerir; ilgili hareketi videoda bul.</small>':''}`;dialog.showModal?dialog.showModal():dialog.setAttribute('open','');}
