let mediaFilter3='all',masterFilter3='all',atlasSort3='source',workoutLayout3='cards',p90libFilter3='',p90libPage3=0;
function latestLevel3(id,side){let l=moveStats(id).slice().sort((a,b)=>String(b.date).localeCompare(String(a.date)));return l[0]?.[side+'Level']||'Denemedim'}
function atlasFilterRows3(){return atlasRows().filter(x=>{let m=m3(x.id,x.name),l=moveStats(x.id);return (atlasLevel==='all'||atlasLevel===x.level)&&(!atlasFilter||[x.name,x.id,x.level,x.mode,...Object.values(x.details||{})].join(' ').toLowerCase().includes(atlasFilter.toLowerCase()))&&(mediaFilter3==='all'||mediaFilter3==='video'&&!!m.yt||mediaFilter3==='image'&&!!m.image||mediaFilter3==='missing'&&!m.image&&!m.source&&!m.video)&&(masterFilter3==='all'||masterFilter3==='favorite'&&v2().atlas[x.id]?.favorite||masterFilter3==='trained'&&l.length||masterFilter3==='untrained'&&!l.length)})}
