function atlasTile3(x){let m=m3(x.id,x.name),logs=moveStats(x.id),r=logs.reduce((a,b)=>a+Number(b.right||0),0),l=logs.reduce((a,b)=>a+Number(b.left||0),0);return `<article class="atlas-tile"><button class="atlas-open" onclick="atlasSelected='${x.id}';render();window.scrollTo(0,0)">${thumb3(m)}<div class="tile-text"><div class="flex between"><span class="levelpill ${esc(x.level.toLowerCase())}">${esc(x.level)}</span><span class="muted mini">${x.id}</span></div><h3>${esc(x.name)}</h3><div class="side-pair"><span>Sağ <b>${r}</b></span><span>Sol <b>${l}</b></span></div><small>${m.yt?'▶ Video':m.source?'↗ Kaynak':m.image?'◈ Görsel':'Medya eksik'}</small></div></button><button class="favorite3 ${v2().atlas[x.id]?.favorite?'starred':''}" aria-label="Favori" onclick="moveMeta('${x.id}','favorite',${!v2().atlas[x.id]?.favorite})">${v2().atlas[x.id]?.favorite?'★':'☆'}</button></article>`}
atlasView=function(){let a=atlasRows(),all=a.map(x=>m3(x.id,x.name)),f=atlasFilterRows3();if(atlasSort3==='az')f.sort((a,b)=>a.name.localeCompare(b.name));if(atlasSort3==='media')f.sort((a,b)=>Number(!!m3(b.id,b.name).yt)-Number(!!m3(a.id,a.name).yt)||Number(!!m3(b.id,b.name).image)-Number(!!m3(a.id,a.name).image));let start=atlasPage*24;if(start>=f.length){atlasPage=0;start=0}let x=a.find(x=>x.id===atlasSelected);return `<section class="studio-hero pole-hero"><div><span class="eyebrow">MOVEMENT LIBRARY / 03</span><h2>Find your flow.</h2><p>${a.length} pole hareketi · kişisel sağ-sol gelişimin.</p><div class="flex"><button class="primary" onclick="go('pole')">Antrenman planı</button><button onclick="go('media')">Medya merkezi</button></div></div><div class="hero-art">◈</div></section><div class="metrics3"><div><small>Hareket</small><b>${a.length}</b></div><div><small>Görsel adresi</small><b>${all.filter(m=>m.image).length}</b></div><div><small>Video bağlantısı</small><b>${all.filter(m=>m.yt).length}</b></div><div><small>Çalışılan hareket</small><b>${a.filter(x=>moveStats(x.id).length).length}</b></div></div>${x?moveDetail(x):''}<div class="card filters3"><div class="flex"><input placeholder="Hareket ara" aria-label="Hareket ara" value="${esc(atlasFilter)}" oninput="atlasFilter=this.value;atlasPage=0;searchRender(this)"><select aria-label="Seviye" onchange="atlasLevel=this.value;atlasPage=0;render()">${['all','Basic','Intermediate','Advanced'].map(x=>`<option value="${x}" ${x===atlasLevel?'selected':''}>${x==='all'?'Tüm seviyeler':x}</option>`).join('')}</select><select aria-label="Medya" onchange="setMediaFilter3('media',this.value)">${[['all','Tüm medya'],['video','Videolu'],['image','Görselli'],['missing','Medya bekliyor']].map(([k,t])=>`<option value="${k}" ${k===mediaFilter3?'selected':''}>${t}</option>`).join('')}</select><select aria-label="Çalışma durumu" onchange="setMediaFilter3('master',this.value)">${[['all','Tümü'],['favorite','Favoriler'],['trained','Çalıştıklarım'],['untrained','Çalışılmamış']].map(([k,t])=>`<option value="${k}" ${k===masterFilter3?'selected':''}>${t}</option>`).join('')}</select><select aria-label="Sıralama" onchange="atlasSort3=this.value;atlasPage=0;render()"><option value="source" ${atlasSort3==='source'?'selected':''}>Atlas sırası</option><option value="az" ${atlasSort3==='az'?'selected':''}>A–Z</option><option value="media" ${atlasSort3==='media'?'selected':''}>Önce medya</option></select></div><small>${f.length} sonuç · görseller çevrimiçi kaynaklardan yüklenir; eksikler açıkça belirtilir.</small></div><div class="atlas-gallery">${f.slice(start,start+24).map(atlasTile3).join('')||'<p class="muted">Sonuç yok. Filtreleri değiştir.</p>'}</div><div class="pager3"><button ${atlasPage===0?'disabled':''} onclick="atlasPage--;render()">‹ Önceki</button><small>${atlasPage+1} / ${Math.max(1,Math.ceil(f.length/24))}</small><button ${start+24>=f.length?'disabled':''} onclick="atlasPage++;render()">Sonraki ›</button></div>`};
const originalDetail3=moveDetail;moveDetail=function(x){let m=m3(x.id,x.name),old=originalDetail3(x),first=old.indexOf('<div class="grid"><div>'),last=old.indexOf('<form onsubmit="logMove',first);let media=`<div class="grid detail-grid3"><div>${thumb3(m)}<small>${esc(m.credit||'Henüz doğrulanmış hareket medyası yok.')}${m.custom?' · kişisel medya':''}</small>${mediaFields3(m)}<div class="side-pair"><span>Sağ <b>${esc(latestLevel3(x.id,'right'))}</b></span><span>Sol <b>${esc(latestLevel3(x.id,'left'))}</b></span></div>${mediaEditor3(m)}<p><a href="${sources.atlas}" target="_blank" rel="noopener">Orijinal atlas ↗</a></p></div>`;return first>=0&&last>=0?old.slice(0,first)+media+old.slice(last):old};
// Compact workout cards remove sideways form scrolling. Each row retains its original set index.
function p90card3(d,n,m,i){let key=d+'-'+i,z=p90entry(n).moves?.[key]||{},media=m3(key,m,'p90');return `<article class="workout-card3 ${z.done?'complete3':''}"><div class="flex between"><span class="eyebrow">SET ${i+1}</span><label class="done3"><input type="checkbox" ${z.done?'checked':''} onchange="p90Move('${key}','done',this.checked);render()"> Tamam</label></div><h3>${esc(m)}</h3>${media.yt?`<button onclick="showMedia3('p90','${key}')">▶ Grup videosu</button>`:''}<div class="flex mini"><a href="${mediaSearch3(m,'p90','video')}" target="_blank" rel="noopener">Video ara ↗</a><a href="${mediaSearch3(m,'p90','img')}" target="_blank" rel="noopener">Görsel ara ↗</a><button onclick="showExercise3('${key}')">Medya / detay</button></div><div class="repgrid3">${[['reps','Tekrar'],['right','Sağ'],['left','Sol'],['kg','Kg'],['seconds','Sn']].map(([k,t])=>`<label>${t}<input type="number" aria-label="${esc(m)} ${t}" min="0" step="${k==='kg'?'0.5':'1'}" value="${esc(z[k]??'')}" onchange="p90Move('${key}','${k}',this.value)"></label>`).join('')}</div></article>`}
function showExercise3(id){let x=p90Catalog3().find(x=>x.id===id);if(!x)return;let m=m3(id,x.name,'p90'),d=$('#mediaDialog3');d.innerHTML=`<div class="dialog-head"><h2>${esc(x.name)}</h2><button onclick="closeMedia3()" aria-label="Kapat">×</button></div>${thumb3(m)}<p class="muted">${esc(m.credit||'Bu set için henüz tekil hareket videosu eklenmedi.')}</p>${mediaFields3(m)}${mediaEditor3(m)}`;d.showModal?d.showModal():d.setAttribute('open','')}
