function mediaCenter3(){let a=atlasRows().map(x=>m3(x.id,x.name)),p=p90Catalog3(),f=p.filter(x=>!p90libFilter3||x.name.toLowerCase().includes(p90libFilter3.toLowerCase())||DVD[x.d].toLowerCase().includes(p90libFilter3.toLowerCase())),start=p90libPage3*24;return `<section class="studio-hero"><div><span class="eyebrow">MUSES / MEDIA LIBRARY</span><h2>Watch. Learn. Move.</h2><p>Kaynağı belli görsel ve videolar; kişisel kayıtlar ve eksik medya listesi.</p><button class="primary" onclick="mediaFilter3='video';atlasPage=0;go('atlas')">Pole videoları</button></div><div class="hero-art">▶</div></section><div class="metrics3"><div><small>Pole görsel</small><b>${a.filter(m=>m.image).length}/${a.length}</b></div><div><small>Pole video</small><b>${a.filter(m=>m.yt).length}/${a.length}</b></div><div><small>P90X set</small><b>${p.length}</b></div><div><small>Grup video eşleşmesi</small><b>${p.filter(x=>m3(x.id,x.name,'p90').yt).length}</b></div></div><div class="card"><h3>Kaynaklar</h3><div class="media-actions"><a href="https://polemovebook.com/collection/Bare-Necessities" target="_blank" rel="noopener">PoleMovebook</a><a href="https://polepedia.com/move-dictionary/" target="_blank" rel="noopener">PolePedia</a><a href="https://www.acefitness.org/resources/everyone/exercise-library/" target="_blank" rel="noopener">ACE Exercise Library</a><button onclick="mediaFilter3='missing';atlasPage=0;go('atlas')">Eksik pole medyası</button></div><p class="muted mini">Harici medya canlı olarak yüklenir. Kitap veya video dosyaları kopyalanmadı. Video başlığı ve kaynak eşleşmesi kontrol edildi; bu cihazda ağ oynatımı doğrulanmadı.</p></div><div class="card"><h2>P90X · Hareket medyası</h2><input placeholder="P90X hareketi veya DVD ara" value="${esc(p90libFilter3)}" oninput="p90libFilter3=this.value;p90libPage3=0;searchRender(this)"><small> ${f.length} set satırı</small></div><div class="atlas-gallery">${f.slice(start,start+24).map(x=>{let m=m3(x.id,x.name,'p90');return `<article class="atlas-tile"><button class="atlas-open" onclick="showExercise3('${x.id}')">${thumb3(m)}<div class="tile-text"><span class="tag">DVD ${x.d}</span><h3>${esc(x.name)}</h3><small>${m.yt?'▶ Video kaynağı':m.custom?'Kişisel medya':'Arama / medya ekle'}</small></div></button></article>`}).join('')}</div><div class="pager3"><button ${p90libPage3===0?'disabled':''} onclick="p90libPage3--;render()">‹ Önceki</button><small>${p90libPage3+1}/${Math.max(1,Math.ceil(f.length/24))}</small><button ${start+24>=f.length?'disabled':''} onclick="p90libPage3++;render()">Sonraki ›</button></div>`}
function audit3(){let a=atlasRows().map(x=>m3(x.id,x.name)),p=p90Catalog3(),r=resourceRows(),b=bookRows(),rows=[['Pole hareketleri',a.length,a.length,'Atlas başlıkları'],['Pole görsel bağlantıları',a.filter(x=>x.image).length,a.length,'Çevrimiçi adres; oynatma/yükleme garantisi yok'],['Pole doğrudan YouTube',a.filter(x=>x.yt).length,a.length,'Bazıları kombinasyon videosu'],['P90X set satırları',p.length,p.length,'Takip defteri'],['P90X video eşleşmesi',p.filter(x=>m3(x.id,x.name,'p90').yt).length,p.length,'Çok hareketli video; tekil çekim değil'],['İngilizce kaynakları',r.length,r.length,'Başlık arşivi'],['Gerçek ders aktarımı',recordObjects('İngilizce bölümler').length,null,'Notion bağlantısı gerekli; yerel şablonlar ayrı'],['Kitaplar',b.filter(x=>!x.title.includes('seçilecek')).length,null,'Yerel arşiv'],['Kitap kapakları',b.filter(x=>x.cover).length,b.length,'Baskıya göre seçilmeli'],['Kitap sayfa bilgisi',b.filter(x=>x.pages>0).length,b.length,'Kaydedilen baskı bilgisi'],['Kelime kayıtları',S.words.length,null,'Tam arşiv için Drive/CSV aktarımı']];return `<div class="card"><div class="flex between"><h2>Veri sağlığı · canlı denetim</h2><span class="tag">v0.3</span></div><p>Gerçek kayıt sayıları; olmayan veri tamamlanmış sayılmaz.</p>${rows.map(([t,n,total,detail])=>`<div class="auditrow3"><div><b>${esc(t)}</b><small>${esc(detail)}</small></div><div><b>${n}${total!==null?'/'+total:''}</b>${total!==null?`<div class="bar"><i style="width:${Math.min(100,n/Math.max(1,total)*100)}%"></i></div>`:''}</div></div>`).join('')}<p class="notice">Notion ve Drive'a yazma/senkronizasyon yerel HTML'de etkin değil. Mevcut kayıtları korumak için güncellemeden önce JSON yedeği al.</p></div>`}
