let all4=[],by4=new Map(),root4=new Map(),list4=[],queue4=[],pos4=0,side4=false,tab4='study',search4='',shuffle4=false,auto4=false,timer4=null,result4=null,answer4='',chosen4=new Set(),page4=0,graphLevel4='All',graphStatus4='All',rootSel4='',rootSearch4='',matchPick4=null,matchDone4=new Set(),matchOrder4=[],full4=false,session4=null,dictBusy4=false,goalPeriod4='month',graphPeriod4=30,chartDay4='',goalModule4='resource',quizOptions4=[],statsCache4=null;
function refresh4(){let m=new Map(DB4.map(w=>[key4(w),w]));for(let w of S.words||[]){let k=key4(w);if(w['Word / Phrase']&&!m.has(k)&&!(w['Source']==='Example'))m.set(k,{...w,_key:k,Lists:['Kişisel eklemeler'],Levels:[]})}all4=[...m.values()];by4=new Map(all4.map(w=>[key4(w),w]));list4=['All',...new Set(all4.flatMap(w=>w.Lists||[]))];root4=new Map();for(let w of all4){let ls=w.Lists||[];for(let l of ls.filter(x=>x.startsWith('ROOT'))){let name=l.replace(/^ROOT [AB] — /,'');if(!root4.has(name))root4.set(name,[]);root4.get(name).push(key4(w))}}statsCache4=null}
