function rating4(n){let w=cur4();if(!w)return;let k=key4(w),a=st4(k),d=today(),same=a.last===d,success=n<=3&&(!result4||result4.ok!==false);let stage=same?(a.stage||0):success?Math.min(4,(a.stage??-1)+1):0;let days=a.days.slice();if(success&&!days.includes(d))days.push(d);let next=add(d,iv4[n][stage]);let p={level:n,stage,last:d,next,days,attempts:(a.attempts||0)+1,correct:(a.correct||0)+(success?1:0)};if(!success)p.lastFail=d;let was=master4(a);update4(k,p);S.reviews.push({key:k,date:d,level:n,mode:'v4-'+s4().mode,result:success?'correct':'incorrect'});if(session4){session4.count++;session4.correct+=success?1:0}save();if(!was&&master4(st4(k))){sound('unlock');toast('🏅 Kelime uzmanlığı: '+w['Word / Phrase'])}else{sound(success?'win':'tap');toast('Sonraki SRS: '+next)}move4(1)}
function norm4(t){return String(t||'').normalize('NFKC').toLocaleLowerCase('en').trim().replace(/[.!?]+$/,'').replace(/\s+/g,' ')}
