function compare4(a,b){a=norm4(a);b=norm4(b);let row=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let prev=row[0];row[0]=i;for(let j=1;j<=b.length;j++){let old=row[j];row[j]=Math.min(row[j]+1,row[j-1]+1,prev+(a[i-1]!==b[j-1]));prev=old}}return Math.max(0,Math.round(100*(1-row[b.length]/Math.max(a.length,b.length,1))))}
function evaluate4(v,spoken=false,confidence=null){let w=cur4();if(!w)return;let f=spoken?s4().speak:s4().write,t=label4(w,f);if(!t){toast('Bu hedef alanı boş.');return}let opts=variants4(t,f),score=Math.max(...opts.map(x=>compare4(x,v))),ok=spoken?score>=85:opts.includes(norm4(v));result4={ok,score,transcript:v,expected:t,confidence,spoken};answer4=v;side4=true;let k=key4(w),a=st4(k),d=today();if(ok){if(spoken)update4(k,{speaks:[...a.speaks.filter(x=>x.date!==d),{date:d,score}]});else update4(k,{writes:[...new Set([...a.writes,d])]});sound('win')}render()}
