const units4={resource:'bölüm',book:'sayfa',vocab:'başarılı kelime',p90:'gün',pole:'hareket oturumu',swim:'metre',habit:'gün'};
function goalChoices4(m){if(m==='resource')return resourceRows().map(r=>[r.id,r.title]);if(m==='book')return bookRows().filter(b=>b.pages>0).map(b=>[b.id,b.title]);if(m==='vocab')return [['All','Tüm seviyeler'],...LV4.map(l=>[l,l])];if(m==='habit')return habits.filter(x=>x[1]).map(x=>[x[0],x[0]]);return [['all',({p90:'P90X turu',pole:'Pole hareket kaydı',swim:'Yüzme mesafesi'})[m]]]}
