agendaRows5=function(d){let all=priorAgenda5(d),tasks=all.filter(x=>x.kind==='task'),goals=all.filter(x=>x.kind==='challenge'),legacy=all.filter(x=>x.kind==='legacy');let rows=[...tasks,...goals.filter(g=>!tasks.some(t=>t.module===g.module&&t.target===g.target&&t.date===g.date)),...legacy.filter(e=>!tasks.some(t=>t.module===e.module&&t.target&&['p90','swim'].includes(t.module))&&!goals.some(g=>g.module===e.module&&['p90','swim'].includes(g.module)))];return [...rows,...unplanned5(d,rows)].sort((a,b)=>(a.time||'99:99').localeCompare(b.time||'99:99'))};
